from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from webpush.models import PushInformation
from webpush.utils import send_notification_to_user

class SendTestPushNotificationView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        sub_id = request.data.get("subscription_id")
        payload = request.data.get("payload", {})

        # Verify subscription belongs to the calling user
        push_info = PushInformation.objects.filter(id=sub_id, user=request.user).first()
        if not push_info:
            return Response({"error": "Push subscription not found"}, status=status.HTTP_404_NOT_FOUND)

        send_notification_to_user(request.user, payload)
        return Response({"status": "Notification dispatched", "subscription_id": sub_id}, status=status.HTTP_200_OK)
